INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0175', 'D-SCHEMA', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-A: item_population_links are SUBSTRATE, provisionally -- any edge a determination relies on must be re-derived and carry a rationale_ref in that determination''s own migration.', 'ADOPTED by owner ruling 2026-08-31. Unblocks every determination. The alternative readings were substrate-unconditionally (rejected: writes the debt off) and scaffolding (rejected: makes no cell determinable anywhere).', 'Measured 2026-08-31 against the live schema: item_population_links holds 372 rows and rationale_ref is NULL in ALL 372; 358 of them were written by one session, session_2026-05-11-items-population-normalization, with 9 from session_2026-07-24-e08-inclusion-repair and 5 from session_2026-07-13-contradiction-sweep-f07-recovery. So the concern is real and concentrated, not diffuse. ''Provisionally'' converts 372 silent assertions into a debt paid where it is used rather than all at once or never. This is the ruling the instrument blocks step 5 behind, and it is F-5 in the 2026-08-22 agonist-antagonist plan.', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-item-population-links-are-substrate-provisionally.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-A", "decisions/DR-2026-08-19-research-restart-operative-instrument.md \u00a73 step 4a"]', '["Substrate unconditionally -- rejected: the 2026-05-11 session''s assertions would never be examined and the debt is written off rather than paid.", "Scaffolding, quarantined under D-1 -- rejected: it makes NO cell determinable anywhere until all 372 are re-derived, which stops determination work entirely."]', 'THE OBLIGATION NEEDS AN ENFORCER OR IT DECAYS. ''Provisionally'' is a standing requirement on every future determination migration; with nothing reading it, it becomes ''substrate unconditionally'' by inattention -- CLAUDE.md §1''s ratchet running the other way. A check is owed that fails a determination migration citing an item_population_links edge whose rationale_ref is still NULL. NOT built in this batch: the first such migration does not exist yet, so the check would be vacuous today (§2a), and its subject arrives with OD-B''s links. INTERACTION WITH THE PARKED RENAME: migration 065 folds item_population_links into base_item_taxonomy_links and DROPS rationale_ref, justified by it being 0 of 372 populated. OD-A makes that column the place the debt is paid. The 065 generator must be corrected before it lands.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0176', 'D-DOCT', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-B: deaf and hard-of-hearing people belong on room-acoustic-performance. Add DEAF and COM to A-18 and A-03/A-06/A-07.', 'ADOPTED by owner ruling 2026-08-31.', 'Measured 2026-08-31: DEAF carries 16 item_population_links across the schema and COM carries 34, and NEITHER appears on any of A-18, A-03, A-06 or A-07 -- zero links. Yet the slug''s only Tier-1-anchored value is theirs. Reverberation is the paradigm access barrier for hearing-aid and cochlear-implant users, and the reasoning doc''s own step 2 names them the worst-case user. A chapter on room acoustics that omits deaf people is not defensible. This is F-6 in the 2026-08-22 plan.', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-deaf-and-com-belong-on-room-acoustic-performance.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-B"]', '["Yes, DEAF only, holding COM pending its own evidence -- narrower per-population but leaves a second gap open on the same slug.", "No, leave the slug as it stands -- rejected: the slug''s strongest evidence is about deaf people."]', 'These are the FIRST edges written under OD-A''s obligation, so they are its proof of shape: each must carry a rationale_ref in the migration that writes it, and that migration is where the pattern is set for every determination after. Not written in this batch -- the links are an act, and this row is the ruling that authorises it.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0177', 'D-DOCT', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-C: A-18 ''RT60 in Occupied Learning and Listening Spaces'' applies to DEAF, AUT, NDV and DEM -- the reasoning doc''s four, minus ''general''.', 'ADOPTED by owner ruling 2026-08-31. Unblocks A-18 and gives its 12 staged standards leads a home.', 'Measured 2026-08-31: A-18 exists in items and carries ZERO item_population_links, which is what BRK-20 recorded and why the 2026-08-20 adversarial adjudication refused to author A-18 x AUT -- authoring it then would have rendered a coverage failure as an epistemic finding. ''general'' is dropped because it is not a disability population; admitting it would re-introduce the population umbrella CLAUDE.md §6 forbids, and the project''s stated frame is ICF/access-need with codes AND names, never umbrellas. All four adopted codes are live in populations (DEAF, AUT, NDV, DEM verified present).', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-a18-applies-to-deaf-aut-ndv-dem.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-C"]', '["All four including ''general'' -- rejected: contradicts CLAUDE.md \u00a76''s bar on umbrellas and would be reversed later.", "Defer and let evidence settle the set -- consistent with D-0174 (applicability is a synthesis judgement) but keeps A-18 blocked and its 12 leads homeless."]', 'Tension worth stating rather than hiding: D-0174 holds applicability is a SYNTHESIS judgement, and this ruling fixes an applicability set before synthesis has run. It is defensible as a research FRAME -- the set A-18 will be researched ACROSS -- not as a determination, and it must not be cited later as though synthesis had produced it. The distinction is the same one D-0174 draws between relevance and applicability.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0178', 'D-METH', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-D: a Co-1 tier is unwarranted-pending unless co1_provenance NAMES the co-production. ''published_corpus'' is not a co-production warrant.', 'ADOPTED by owner ruling 2026-08-31, RE-PUT after measurement refuted the question''s own premise.', 'The question as tabled in the 2026-08-22 plan asserted co1_source_type and co1_provenance were NULL on all three Co-1 sources. Measured 2026-08-31, that is FALSE: REF-00965, REF-00966 and REF-00968 all carry co1_source_type=''peer_reviewed_literature'' and co1_provenance=''published_corpus''. The ruled NULL test would therefore have fired on ZERO rows -- a gate that examined nothing (CLAUDE.md §2a), on the only slug in the project that holds evidence. The re-put ruling fixes the substance rather than the field''s nullity: ''published_corpus'' states where a source was PUBLISHED, not that disabled people CO-PRODUCED it, and co-production is the entire Co-1 warrant under CRPD Art 4.3. CLAUDE.md §6: ''when you cite lived-experience work, the disabled people who produced it are part of the evidence, not metadata.''', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-co1-warrant-must-name-the-co-production.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-D", "governance/tier-system.md"]', '["Keep the NULL test as first ruled -- rejected on measurement: it examines nothing here.", "Defer entirely pending full texts -- weighed; nothing blocks on it, but it leaves Co-1 unenforced on the one slug that uses it."]', 'CONSEQUENCE, STATED BECAUSE IT IS UNCOMFORTABLE: all three Co-1 sources are unwarranted-pending under this rule TODAY, including REF-00966 -- which the 2026-08-22 plan says DOES state a participatory method and DOES carry autistic community co-authors. So REF-00966''s RECORD is wrong, not its tier: the fix is to correct co1_provenance upward from the retrieved payload, not to drop the tier. REF-00965 and REF-00968 remain referred, needing full texts this environment cannot reach. ALSO MEASURED: evidence_sources.tier has NO CHECK constraint, so tier is not machine-enforced at all and dbcore.check_values returns an empty set for it -- an enforcing check for this rule cannot lean on the column''s own vocabulary.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0179', 'D-METH', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-E: REF-00967 belongs at T3, not T1. Measured already T3 -- the ruling is satisfied and no re-grade is emitted.', 'ADOPTED by owner ruling 2026-08-31, and found ALREADY IN THE RULED STATE.', 'The ruling stands on its merits without a full text: REF-00967 is an n=27 single-centre EEG study whose own database note concedes it carries no RT60, NRC, STC or NC value, so it cannot anchor an acoustic determination and T1 overstates it. Measured 2026-08-31 before emitting anything: evidence_sources.tier for REF-00967 is ALREADY 3. Either the re-grade was applied after the 2026-08-22 plan was written, or the plan''s premise was stale when tabled. Recorded as satisfied rather than emitting a migration that would change nothing while claiming to have re-graded a source.', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-ref-00967-already-t3.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-E"]', '["Emit the re-grade anyway -- rejected: a data migration whose UPDATE matches the existing value is a false record of an act.", "Leave the tier standing at T1 -- moot; it is not at T1."]', 'Two of this batch''s seven questions carried stale premises (this one and OD-D), both discovered only by measuring before writing. That is CLAUDE.md §2(b) -- prose that contradicts the database -- inside a planning document rather than a rendered one. The plans in workplan/ are not regenerated from the DB and carry no drift stamp.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0180', 'D-OP', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-F: the adversarial-subject waiver is RATIFIED ONCE, NARROWLY -- the 2026-08-22 review is recorded as an owner-commissioned pass over records and plans.', 'ADOPTED by owner ruling 2026-08-31.', 'references/project-standards.md carries a standing rule on what an adversarial pass may take as its subject; the 2026-08-22 review''s subjects were a session record, a census and execution plans, and it ran anyway. Its findings are on the books and shaped this very batch -- OD-A through OD-G are its output. A rule that is silently broken is worse than one that is explicitly waived: the silent break leaves the rule looking intact while its authority is gone. Ratifying once and narrowly keeps the rule for the next pass while making this one honest.', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-adversarial-subject-waiver-ratified-narrowly.md", "references/project-standards.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-F"]', '["Refuse the waiver -- leaves a pass that already shaped the plan on the record as a violation, and invites the same silent break next time.", "Ratify broadly by amending project-standards.md -- cleanest going forward but is a doctrine change wider than the single pass in question."]', 'Scope is one pass, 2026-08-22, and does not extend to the adversarial critique this session ran over migration 065 -- that one''s subject was a migration and its harness, which the rule does not reach.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0181', 'D-OP', 'DG-NON', 'Owner ruling. Population applicability, work-product inclusion and evidence-tier definitions are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable. The operative instrument DR-2026-08-19 §3 step 4a names this batch "THE NEXT ACT, and it is the owner''s, not a session''s".', 'OD-G: strike DR §12.1 Step 10''s jurisdictional_values clause, and record the 2026-08-12 REFERENCE-ONLY ruling in the DB as a row-level note.', 'ADOPTED by owner ruling 2026-08-31.', 'The runbook currently instructs the next research batch to write jurisdictional_values, which a 2026-08-12 ruling made REFERENCE-ONLY -- so the runbook walks the next batch into a forbidden write. That is F-8. The ruling itself lives only in a YAML header comment, which is precisely the class CLAUDE.md rule 4b names: a ruling that is in the repository, in a file, and still fails to bind because the next session''s search does not reach it. Putting it in the DB as a row-level note also stops an emptied-by-ruling table from looking like an empty-for-want-of-data one -- a distinction no gate can currently make.', '2026-08-31 22:14', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-31-strike-jurisdictional-values-clause.md", "workplan/2026-08-22-agonist-antagonist-execution-plan.md \u00a72 OD-G"]', '["Strike the clause only -- fixes the trap but leaves the ruling in a YAML comment where grep will not find it.", "Keep the clause and reverse the REFERENCE-ONLY ruling -- reverses a 2026-08-12 content ruling, which needs its own reasoning rather than being decided as runbook housekeeping."]', 'jurisdictional_values holds 109 rows and is renamed research_code_leads by the parked migration 065; the note must survive that rename. Editing a RATIFIED DR''s runbook is itself unusual and is done here under an explicit owner ruling, with the struck text preserved in the DR record rather than deleted.', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification', '2026-08-31 22:14', 'session_2026-08-31-od-batch-ratification');